def criar_tipos_e_vincular_planos(apps, schema_editor):
    TipoSeguro = apps.get_model("cotacoes", "TipoSeguro")
    Plano = apps.get_model("cotacoes", "Plano")
    for codigo, nome in TIPOS_SEGURO:
        tipo, _ = TipoSeguro.objects.using(schema_editor.connection.alias).get_or_create(
            codigo=codigo,
            defaults={"nome": nome},
        )
        Plano.objects.using(schema_editor.connection.alias).filter(
            tipo_seguro=codigo,
        ).update(tipo_id=tipo.pk)


